INSERT INTO public.app_changelog (version, change_type, title, description) VALUES ('1.3.5.0','minor','Auditorias — Fase 3: Detalhe + Exportação PPTX','Nova tela de detalhe de auditoria com abas (Visão Geral, NCs, Cronograma, Histórico), registro de respostas do fornecedor (foto After + contramedida + data) e geração de PPTX no padrão Mobis (capa Supplier Visit Report, General Issues, Improvement Cases Before/After). Ao gerar o PPTX o status muda para "Aguardando fornecedor".');